131	// complete, the full local chain is replayed.
132	func SafelyAdvanceLocalRef(ctx context.Context, repo *git.Repository, localRefName plumbing.ReferenceName, targetHash plumbing.Hash) error {
133		currentLocal, localErr := repo.Reference(localRefName, true)
134		if localErr != nil {
135			if !errors.Is(localErr, plumbing.ErrReferenceNotFound) {
136				return fmt.Errorf("failed to read local ref %s: %w", localRefName, localErr)
137			}
138			return setRefHash(repo, localRefName, targetHash)
139		}
140	
141		localHash := currentLocal.Hash()
142		if localHash == targetHash {
143			return nil
144		}
